import numpy as np, math
def read(p):
    L=open(p).read().split('\n'); n=int(L[0]); ats=[]; xyz=[]
    for line in L[2:2+n]:
        t=line.split(); ats.append(t[0]); xyz.append([float(x) for x in t[1:4]])
    return ats, np.array(xyz)
ats, X = read('opt1.xyz')
ax = X[8]-X[37]; ax/=np.linalg.norm(ax)   # axial axis
names={19:'Ca',21:'Cb',1:'Zn',66:'H'}
vecs={}
for i,nm in names.items():
    v=X[i]-X[0]; v=v-v.dot(ax)*ax; vecs[nm]=v/np.linalg.norm(v)
    print(nm, 'polar angle from axis', round(math.degrees(math.acos((X[i]-X[0]).dot(ax)/np.linalg.norm(X[i]-X[0]))),1))
e1=vecs['Ca']
e2=np.cross(ax,e1)
for nm,v in vecs.items():
    az=math.degrees(math.atan2(v.dot(e2), v.dot(e1)))%360
    print(nm, 'azimuth', round(az,1))
